; Multicolour VIC-II sprite FRAME SOURCE (not displayed in place).
; Generated by: tools/png_to_c64_sprite.py (make sprites)
;
; Lives in the DATA segment (above $4000). Runtime frames go to $3000 (not under
; title — title is parked at $E000). stage_init copies 12×64 into SPRITE_BLOCK.
;
; Kind mapping (design A/B/C):
;   C = small  = drone1_tiny_*
;   B = medium = drone2_medium_*
;   A = large  = drone3_large_*
; Directions: left = native (nose left), right / up / down = transforms.
; Install order = pointer order $C0..$CB.

.align 64

spr_frames_src:
; --- Drone C (small / tiny) → ptr $C0–$C3 after install ---
spr_drone_c_left:
    .incbin "../../assets/sprites/drone1_tiny_native.bin"
spr_drone_c_right:
    .incbin "../../assets/sprites/drone1_tiny_right.bin"
spr_drone_c_up:
    .incbin "../../assets/sprites/drone1_tiny_up.bin"
spr_drone_c_down:
    .incbin "../../assets/sprites/drone1_tiny_down.bin"

; --- Drone B (medium) → ptr $C4–$C7 ---
spr_drone_b_left:
    .incbin "../../assets/sprites/drone2_medium_native.bin"
spr_drone_b_right:
    .incbin "../../assets/sprites/drone2_medium_right.bin"
spr_drone_b_up:
    .incbin "../../assets/sprites/drone2_medium_up.bin"
spr_drone_b_down:
    .incbin "../../assets/sprites/drone2_medium_down.bin"

; --- Drone A (large) → ptr $C8–$CB ---
spr_drone_a_left:
    .incbin "../../assets/sprites/drone3_large_native.bin"
spr_drone_a_right:
    .incbin "../../assets/sprites/drone3_large_right.bin"
spr_drone_a_up:
    .incbin "../../assets/sprites/drone3_large_up.bin"
spr_drone_a_down:
    .incbin "../../assets/sprites/drone3_large_down.bin"

SPR_FRAMES_SRC_SIZE = 12 * 64       ; 768 bytes (drone bank → $3000)

; --- Player facings (copied into PLAYER_BUF_0 / $3E00 on demand) ---
; Not installed into $3000; slot 0 uses SPR_PTR_PLAYER_0 ($F8).
.align 64
spr_player_left:
    .incbin "../../assets/sprites/player_left.bin"
spr_player_right:
    .incbin "../../assets/sprites/player_right.bin"
spr_player_up:
    .incbin "../../assets/sprites/player_up.bin"
spr_player_down:
    .incbin "../../assets/sprites/player_down.bin"

